export type Event = RunCreatedEvent | RunStatusEvent | RunStoppedEvent | RunFailedEvent | RunCompletedEvent | RunResumedEvent | PlanNeedEvent | PlanSourceEvent | PlanReadyEvent | ApprovalCommittedEvent | PolicyUpdatedEvent | SourceStatusEvent | DocStoredEvent | AgentSpawnedEvent | AgentStatusEvent | AgentLogEvent | AgentMessageEvent | AgentDecisionEvent | GatewayRequestEvent | ItemCreatedEvent | ItemVerifiedEvent | ItemUpdatedEvent | ReportReadyEvent | SummarySentenceEvent | SummaryVerifiedEvent | SummaryReadyEvent | CommentCreatedEvent | CommentResolvedEvent | UsageUpdatedEvent;
export type Item = DataItem | Conclusion | Extrapolation | Chart;
export type Block = ParagraphBlock | BulletsBlock | ChartBlock | ScorecardBlock;
export type Locator = TextLocator | JsonLocator;

export const EVENT_TYPES = ["run.created", "run.status", "run.stopped", "run.failed", "run.completed", "run.resumed", "plan.need", "plan.source", "plan.ready", "approval.committed", "policy.updated", "source.status", "doc.stored", "agent.spawned", "agent.status", "agent.log", "agent.message", "agent.decision", "gateway.request", "item.created", "item.verified", "item.updated", "report.ready", "summary.sentence", "summary.verified", "summary.ready", "comment.created", "comment.resolved", "usage.updated"] as const;
export type EventType = Event["type"];
/** Narrow an event by its type: `isEvent(e, "gateway.request")` gives `e.data` its exact shape. */
export function isEvent<T extends EventType>(e: Event, type: T): e is Extract<Event, { type: T }> {
  return e.type === type;
}
